using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PrecisionMantraActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PrecisionMantraActionCustomDescription", order = 0)]
public class PrecisionMantraActionCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		return (battleAction as PrecisionMantraAction).PrecisionMantraLogicAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
	}
}
